function score(pw){
  if(!pw) return {bits:0, score:0, warning:'empty'};
  var len=pw.length;
  var hasLower=/[a-z]/.test(pw), hasUpper=/[A-Z]/.test(pw), hasDigit=/\d/.test(pw), hasSym=/[^a-zA-Z0-9]/.test(pw);
  var pool=0; if(hasLower)pool+=26; if(hasUpper)pool+=26; if(hasDigit)pool+=10; if(hasSym)pool+=33;
  if(pool===0) pool=1;
  var bits=len*Math.log2(pool);
  var penalty=0;
  var rep=1,maxrep=1; for(var i=1;i<len;i++){ if(pw[i]===pw[i-1]){rep++; if(rep>maxrep)maxrep=rep;} else rep=1; }
  if(maxrep>=3) penalty+=Math.log2(maxrep);
  var seq=1,maxseq=1,code=pw.charCodeAt(0); for(var j=1;j<len;j++){ var c=pw.charCodeAt(j); if(c===code+1||c===code-1){seq++; if(seq>maxseq)maxseq=seq;} else seq=1; code=c; }
  if(maxseq>=3) penalty+=Math.log2(maxseq);
  var uniq={}; for(var k=0;k<len;k++) uniq[pw[k]]=1; var uc=Object.keys(uniq).length; if(uc<len/2) penalty+=Math.log2(len/(uc||1));
  bits=Math.max(0,bits-penalty);
  var s=0; if(bits>=64)s=4; else if(bits>=40)s=3; else if(bits>=20)s=2; else if(bits>=8)s=1; else s=0;
